const patchedAt = new Date().toISOString();

const requestId = pm.collectionVariables.get('requestId');
const url = `${pm.collectionVariables.get('baseUrl')}/api/requests/${requestId}/history`;

pm.sendRequest(
  {
    url,
    method: 'GET',
    header: {
      'X-API-Key': pm.collectionVariables.get('apiKey'),
    },
  },
  (err, res) => {
    pm.test('History request OK', () => {
      pm.expect(err).to.be.null;
      pm.expect(res.code).to.eql(200);
    });

    pm.test('History contains the new status change', () => {
      const body = res.json();
      const items = body.data;
      pm.expect(items).to.be.an('array');

      const last = items[items.length - 1];
      pm.expect(last).to.have.property('toStatus');
      pm.expect(last.toStatus).to.eql('in_progress');

      pm.expect(last).to.have.property('fromStatus');
    });

    pm.test('History is not empty', () => {
      pm.expect(res.json().data.length).to.be.at.least(1);
    });
  }
);

